mecanica.build:
function build(){
    box.innerHTML=Q.map(function(q,i){
      return '<div class="q" data-i="'+i+'"><div class="qh">Questão '+(i+1)+' de '+Q.length+'</div>'+
        '<div class="qt">'+esc(q.q)+'</div>'+
        q.o.map(function(o,j){
          return '<label class="opt" data-j="'+j+'"><input type="radio" name="q'+i+'" value="'+j+'">'+esc(o)+'</label>';
        }).join('')+
        '<div class="q-fb" id="fb-'+i+'"></div></div>';
    }).join('');
  }

mecanica.corrigir:
function corrigir(){
    var acertos=0;
    Q.forEach(function(q,i){
      var sel=document.querySelector('input[name="q'+i+'"]:checked');
      var card=box.querySelector('.q[data-i="'+i+'"]');
      $all('.opt',card).forEach(function(l){l.classList.remove('right','wrong');});
      $all('.opt',card).forEach(function(l){
        var j=parseInt(l.getAttribute('data-j'),10);
        if(j===q.a)l.classList.add('right');
      });
      if(sel){
        var v=parseInt(sel.value,10);
        if(v===q.a){acertos++;}
        else{
          $all('.opt',card).forEach(function(l){
            if(parseInt(l.getAttribute('data-j'),10)===v)l.classList.add('wrong');
          });
        }
      }
      var fb=$id('fb-'+i);
      fb.innerHTML=esc(q.f);
      fb.classList.add('show');
    });
    var sc=$id('quiz-score');
    sc.className='score show '+(acertos>=8?'pass':'fail');
    sc.innerHTML='<div class="big">'+acertos+' / '+Q.length+'</div><div class="msg">'+
      (acertos>=8
        ? 'Critério atingido. A matéria está no ponto de sustentar uma leitura cronometrada diante de um cliente — inclusive a saída de que o enquadramento está adequado.'
        : 'Abaixo do critério de oito acertos. Reveja as questões erradas antes de aplicar a ordem de leitura a uma fatura real: o erro que custa caro numa leitura não é a linha esquecida, é a ordem errada.')+
      '</div>';
  }
